const data = $input.first().json;

const reviewRoot = '/mnt/s/Miscellaneous/Lecture-Notes';

const lectureId = data.lecture_number.replace('/', '-');

// Course-specific Discord destinations
const discordConfig = {
  mustalah: {
    channel_id: '1555679268627808432',
    webhook_url: 'https://discord.com/api/webhooks/REDACTED_ID/REDACTED_TOKEN',
  },

  fiqh: {
    channel_id: '1296818122833264712',
    webhook_url: 'https://discord.com/api/webhooks/REDACTED_ID/REDACTED_TOKEN',
  },

  aqeedah: {
    channel_id: '1294304146052354100',
    webhook_url: 'https://discord.com/api/webhooks/REDACTED_ID/REDACTED_TOKEN',
  },

  adaab: {
    channel_id: '1555680319745695915',
    webhook_url: 'https://discord.com/api/webhooks/REDACTED_ID/REDACTED_TOKEN',
  },
};

// Used if the course is not listed above
const fallbackDiscord = {
  channel_id: '999999999999999999',
  webhook_url: 'https://discord.com/api/webhooks/REDACTED_ID/REDACTED_TOKEN',
};

const courseKey = data.course.trim().toLowerCase();

const discord =
  discordConfig[courseKey] ?? fallbackDiscord;

const finalNotesFile =
  `${reviewRoot}/${courseKey}/lecture-${lectureId}-run-${data.run_id}.md`;

return [{
  json: {
    ...data,

    course: courseKey,
    lecture_id: lectureId,
    final_notes_file: finalNotesFile,

    discord_channel_id: discord.channel_id,
    discord_webhook_url: discord.webhook_url,
  }
}];

const text = $('Read Final Notes').first().json.stdout
  .replace(/\r\n/g, '\n')
  .trim();

const MAX = 1900;

// A heading is a standalone bold line like:
// **Meaning and purpose of Mustalah al-Hadith**
const headingRegex = /^\*\*.+\*\*$/;

// ----------
// 1. Split the full document into heading sections
// ----------

const lines = text.split('\n');
const sections = [];

let current = [];

for (const line of lines) {
  const isHeading = headingRegex.test(line.trim());

  if (isHeading && current.length > 0) {
    sections.push(current.join('\n').trim());
    current = [];
  }

  current.push(line);
}

if (current.length > 0) {
  sections.push(current.join('\n').trim());
}

// ----------
// 2. Split an oversized section cleanly
// ----------

function splitOversizedSection(section) {
  if (section.length <= MAX) {
    return [section];
  }

  const sectionLines = section.split('\n');

  let heading = '';
  let startIndex = 0;

  if (headingRegex.test(sectionLines[0].trim())) {
    heading = sectionLines[0];
    startIndex = 1;
  }

  const points = [];
  let point = [];

  for (let i = startIndex; i < sectionLines.length; i++) {
    const line = sectionLines[i];

    const startsNewPoint =
      /^-\s/.test(line) ||
      /^\d+[.)]\s/.test(line);

    if (startsNewPoint && point.length > 0) {
      points.push(point.join('\n').trim());
      point = [];
    }

    if (point.length > 0 || line.trim() !== '') {
      point.push(line);
    }
  }

  if (point.length > 0) {
    points.push(point.join('\n').trim());
  }

  const result = [];
  let chunk = heading;

  for (const p of points) {
    const candidate = chunk
      ? `${chunk}\n\n${p}`
      : p;

    if (candidate.length <= MAX) {
      chunk = candidate;
      continue;
    }

    if (chunk) {
      result.push(chunk.trim());
    }

    if (p.length > MAX) {
      const subchunks = splitLongPoint(p);
      result.push(...subchunks);
      chunk = '';
    } else {
      chunk = p;
    }
  }

  if (chunk) {
    result.push(chunk.trim());
  }

  return result;
}

// ----------
// 3. Fallback for one unusually long point
// ----------

function splitLongPoint(point) {
  if (point.length <= MAX) {
    return [point];
  }

  // Prefer sentence boundaries
  const sentences = point.match(/[^.!?]+[.!?]+(?:\s|$)|[^.!?]+$/g) || [point];

  const result = [];
  let chunk = '';

  for (const sentence of sentences) {
    const clean = sentence.trim();

    const candidate = chunk
      ? `${chunk} ${clean}`
      : clean;

    if (candidate.length <= MAX) {
      chunk = candidate;
    } else {
      if (chunk) {
        result.push(chunk.trim());
      }

      // Absolute last resort
      if (clean.length > MAX) {
        for (let i = 0; i < clean.length; i += MAX) {
          result.push(clean.slice(i, i + MAX));
        }
        chunk = '';
      } else {
        chunk = clean;
      }
    }
  }

  if (chunk) {
    result.push(chunk.trim());
  }

  return result;
}

// ----------
// 4. Produce final Discord messages
// ----------

const chunks = [];

for (const section of sections) {
  chunks.push(...splitOversizedSection(section));
}

return chunks.map((content, index) => ({
  json: {
    content,
    part: index + 1,
    total_parts: chunks.length,
    length: content.length,
  }
}));
